CREATE INDEX IX_orders_tenant_created_status
    ON orders (tenant_id, created_at, status)
    INCLUDE (total);            -- stored in the leaf, not part of the sort key

-- Seeks on tenant_id and created_at (both key columns usable)
SELECT id, total FROM orders
WHERE tenant_id = 42 AND created_at >= '2026-01-01';

-- Seeks on tenant_id only: status comes after a skipped column
SELECT id FROM orders WHERE tenant_id = 42 AND status = 'open';

-- Cannot seek at all: the leading column is not constrained
SELECT id FROM orders WHERE created_at >= '2026-01-01';
